package pca

// Doctor texts (remediation advice and the CLI usage), word for word.

const (
	DoctorSuitesRemediation     = "Set the verifier's allowedSuites to exactly the suites your issuers sign with (names from SIG_SUITES), e.g. ['ed25519'] or ['hybrid-ed25519-ml-dsa-65']."
	DoctorPqRemediation         = "Never set allowUnboundPq. For pure-PQ or hybrid roots, configure pqPins (issuer Ed25519 identity -> PQ public key, from pqPinFor) or verify against your stored root grant (trustedRoot; requirePCA / verifyPCActnCore do this)."
	DoctorClockRemediation      = "Synchronise every verifier, issuer and replay-store host with NTP (chrony or systemd-timesyncd) and alert on drift. PCA tolerates at most 60 s between any two clocks (PCACTN_MAX_SKEW_MS); replay retention is exp + skew, so a clock outside that bound can free a nonce early or reject fresh actions."
	DoctorProxyRemediation      = "Set TRUSTED_PROXY_COUNT to exactly the number of reverse proxies in front of the API that APPEND to the trusted header (1 behind one load balancer / ingress; 0 when clients connect directly), and TRUSTED_PROXY_HEADER to the header they write. Too high lets a client pick its own rate-limit bucket with extra X-Forwarded-For entries; too low merges every client into the proxy's bucket."
	DoctorAtomicityRemediation  = "Make consumeOnce / advance one atomic operation on the shared store, e.g. Postgres INSERT .. ON CONFLICT (key) DO UPDATE .. WHERE until < $now RETURNING and UPDATE .. WHERE counter < $n RETURNING, Redis SET key NX PX or a Lua compare-and-set; never read, then write. Then run the full kit: pca-store-conformance --adapter <your adapter>."
	DoctorDurabilityRemediation = "Keep consumed keys and counters in a store with synchronous, persistent commits (Postgres synchronous_commit=on; Redis appendfsync always and maxmemory-policy noeviction), shared by every verifier instance. An in-memory store is only correct for a single process whose lifetime covers the action lifetime."
	DoctorCaveatRemediation     = "Upgrade @atlasauth/pca to >= 0.4.1 in the deployed application (root caveats outside the envelope are enforced from 0.4.1), redeploy, and re-run pca-doctor with --pca-dir pointing at the application."
	DoctorUsage                 = "pca-doctor [--url <deployment>] [options]\n\n  --url URL              the live deployment (base URL of the API that verifies PCActns)\n  --config FILE          JSON or JS config (see the pca-doctor guide); env and flags override it\n  --store MODULE         replay-store adapter module (store conformance kit interface) for the atomicity / durability checks\n  --store-option k=v     passed to the adapter factory (repeatable)\n  --reference URL|local  clock reference (default https://www.google.com/generate_204)\n  --max-skew-ms N        clock fail threshold (default 60000)\n  --trusted-proxy-count N, --proxy-header H, --proxy-hops N   the deployment's proxy settings and the real hop count\n  --pca-dir DIR          the deployed application's directory (its installed @atlasauth/pca is probed)\n  --only a,b | --skip a,b   check groups: clock, store, proxy, suites, caveats\n  --no-probe             do not send forged forwarding headers to the deployment\n  --strict               warnings fail too\n  --json                 machine-readable output\n\nEnv: PCA_DOCTOR_URL, PCA_DOCTOR_REFERENCE_URL, PCA_DOCTOR_STORE, TRUSTED_PROXY_COUNT, TRUSTED_PROXY_HEADER, PCA_TRUSTED_PROXY_HOPS,\n     PCA_ALLOWED_SUITES (comma list), PCA_PQ_PINS (JSON), PCA_ALLOW_UNBOUND_PQ."
)
